<?php $historyActions=['updated'=>'Modification','archived'=>'Archivage','restored'=>'Restauration','validation.approved'=>'Validation','validation.rejected'=>'Reprise demandée','time.created'=>'Temps ajouté','time.updated'=>'Temps modifié','time.deleted'=>'Temps supprimé']; ?>
<section id="history" class="panel tracking-panel" data-ticket-panel data-ticket-live aria-labelledby="ticket-tab-history" hidden><div class="panel-header"><div><h2>Historique détaillé</h2><p>Auteur, date et valeurs avant/après chaque modification depuis l’activation du suivi.</p></div><?= icon('clock') ?></div>
<div class="history-timeline">
<?php $previousHistoryDay=''; foreach($history['entries'] as $event): $historyDay=substr($event['created_at'],0,10);$historyActor=$event['actor_name']??'Système / demande externe'; ?>
<article class="history-timeline-entry" data-history-event><h3 class="history-day" data-history-day <?= $historyDay===$previousHistoryDay?'hidden':'' ?>><?= e($historyDay) ?></h3><div class="history-timeline-row"><span class="history-marker" aria-hidden="true"><?= icon(str_starts_with($event['action'],'time.')?'clock':'edit') ?></span><div class="history-event-body"><header><?= avatar($historyActor,'small',$event['actor_id']?(int)$event['actor_id']:null) ?><strong><?= e($historyActor) ?></strong><span class="history-action" data-history-action="<?= e($event['action']) ?>"><?= e($historyActions[$event['action']]??'Modification') ?></span><time datetime="<?= e(str_replace(' ','T',$event['created_at']).'Z') ?>"><?= e($event['created_at']) ?> UTC</time></header><dl class="history-changes"><?php foreach($event['changes'] as $change): ?><div><dt><?= e($change['label']) ?></dt><dd><?php if($change['field']==='description' || mb_strlen($change['before_label'].$change['after_label'])>500): ?><details><summary>Voir les valeurs</summary><?php endif; ?><div class="history-before"><small>Avant</small><span><?= e($change['before_label']) ?></span></div><div class="history-after"><small>Après</small><span><?= e($change['after_label']) ?></span></div><?php if($change['field']==='description' || mb_strlen($change['before_label'].$change['after_label'])>500): ?></details><?php endif; ?></dd></div><?php endforeach; ?></dl></div></div></article>
<?php $previousHistoryDay=$historyDay; endforeach; if(!$history['entries']): ?><p class="empty-state">Aucune modification enregistrée pour ce ticket.</p><?php endif; ?></div>
<?php if($history['total']>$history['limit']): ?><nav class="pagination" aria-label="Pages de l’historique"><?php if($history['offset']): ?><a class="button subtle" href="<?= e(ticket_url((int)$ticket['id'],'#history',['history_offset'=>max(0,$history['offset']-$history['limit'])])) ?>">Plus récentes</a><?php endif; ?><span><?= $history['offset']+1 ?>–<?= min($history['total'],$history['offset']+$history['limit']) ?> sur <?= $history['total'] ?></span><?php if($history['offset']+$history['limit']<$history['total']): ?><a class="button subtle" href="<?= e(ticket_url((int)$ticket['id'],'#history',['history_offset'=>($history['offset']+$history['limit'])])) ?>">Plus anciennes</a><?php endif; ?></nav><?php endif; ?></section>

<script src="<?= e(asset_url('ticket-history.js')) ?>" defer></script>
